css:
.macro-sim-container {
    padding: 28px;
    background: #0a0f1e;
    min-height: 100vh;
    font-family: 'Courier New', 'SF Mono', 'Consolas', monospace;
    color: #e0e6f0;
}
.macro-sim-header {
    border-left: 4px solid #00bfff;
    padding: 24px 28px;
    margin-bottom: 28px;
    background: rgba(0,191,255,0.04);
    border-radius: 0 8px 8px 0;
}
.macro-sim-header-badge {
    font-size: 0.65rem;
    letter-spacing: 0.2em;
    color: #00bfff;
    margin-bottom: 8px;
    opacity: 0.8;
}
.macro-sim-header h1 {
    color: #00bfff;
    font-size: 1.5rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    margin: 0 0 6px 0;
    font-weight: 700;
}
.macro-sim-subtitle {
    color: #6b7e99;
    font-size: 0.85rem;
    margin: 0;
    letter-spacing: 0.04em;
}
.macro-sim-period-counter {
    text-align: center;
    font-size: 0.85rem;
    color: #6b7e99;
    margin-bottom: 24px;
    letter-spacing: 0.1em;
    text-transform: uppercase;
}
.macro-sim-period-counter span#currentDay,
.macro-sim-period-counter span#maxPeriods {
    color: #00bfff;
    font-weight: 700;
    font-size: 1rem;
}
.macro-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 16px;
    margin-bottom: 28px;
}
.macro-sim-kpi-card {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 20px 18px;
    position: relative;
    overflow: hidden;
    transition: border-color 0.2s ease;
}
.macro-sim-kpi-card:hover {
    border-color: #2a4060;
}
.macro-sim-kpi-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 2px;
    background: linear-gradient(90deg, #00bfff, #0077b6);
}
.macro-sim-kpi-primary::before {
    background: linear-gradient(90deg, #00ff88, #00bfff);
}
.macro-sim-kpi-label {
    color: #6b7e99;
    font-size: 0.65rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    margin-bottom: 10px;
}
.macro-sim-kpi-value {
    font-size: 1.6rem;
    font-weight: 700;
    color: #00bfff;
}
.macro-sim-kpi-primary .macro-sim-kpi-value {
    font-size: 1.8rem;
    color: #00ff88;
}
.macro-sim-briefing {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-left: 3px solid #ff6b35;
    border-radius: 0 8px 8px 0;
    padding: 24px;
    margin-bottom: 24px;
}
.macro-sim-briefing-tag {
    font-size: 0.6rem;
    letter-spacing: 0.18em;
    color: #ff6b35;
    margin-bottom: 12px;
    font-weight: 700;
}
.macro-sim-briefing h3 {
    color: #ffa94d;
    font-size: 1.05rem;
    margin: 0 0 12px 0;
    font-weight: 700;
}
.macro-sim-briefing p {
    color: #c0c8d8;
    font-size: 0.82rem;
    line-height: 1.65;
    margin: 0;
}
.macro-sim-indicators {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 20px 24px;
    margin-bottom: 28px;
    overflow-x: auto;
}
.macro-sim-table-wrap {
    overflow-x: auto;
}
.macro-sim-data-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.78rem;
    margin-top: 10px;
}
.macro-sim-data-table thead th {
    color: #6b7e99;
    font-size: 0.65rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    padding: 8px 12px;
    border-bottom: 1px solid #1f2d3d;
    text-align: center;
}
.macro-sim-data-table thead th:first-child {
    text-align: left;
}
.macro-sim-data-table tbody td {
    padding: 7px 12px;
    text-align: center;
    border-bottom: 1px solid rgba(31,45,61,0.5);
    color: #c0c8d8;
}
.macro-sim-data-table tbody td:first-child {
    text-align: left;
    color: #8899aa;
    font-size: 0.72rem;
    letter-spacing: 0.04em;
}
.macro-sim-data-table .macro-sim-warn {
    color: #ffa94d;
}
.macro-sim-data-table .macro-sim-danger {
    color: #ff4757;
    font-weight: 700;
}
.macro-sim-controls {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 28px;
    margin-bottom: 28px;
}
.macro-sim-controls h3 {
    color: #00bfff;
    font-size: 0.95rem;
    margin: 0 0 20px 0;
    letter-spacing: 0.06em;
}
.macro-sim-input-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 18px;
    margin-bottom: 18px;
}
.macro-sim-input-group {
    display: flex;
    flex-direction: column;
}
.macro-sim-input-group label {
    color: #8899aa;
    font-size: 0.68rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin-bottom: 8px;
}
.macro-sim-input-group input[type="number"] {
    background: #0a0f1e;
    border: 1px solid #2a4060;
    color: #e0e6f0;
    border-radius: 6px;
    padding: 10px 14px;
    font-family: 'Courier New', monospace;
    font-size: 1.1rem;
    font-weight: 700;
    width: 100%;
    box-sizing: border-box;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.macro-sim-input-group input[type="number"]:focus {
    outline: none;
    border-color: #00bfff;
    box-shadow: 0 0 8px rgba(0,191,255,0.2);
}
.macro-sim-input-hint {
    color: #4a5568;
    font-size: 0.62rem;
    margin-top: 5px;
    letter-spacing: 0.06em;
}
.macro-sim-cash-bar {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 14px 18px;
    background: rgba(0,191,255,0.06);
    border: 1px solid rgba(0,191,255,0.15);
    border-radius: 6px;
    margin-bottom: 20px;
}
.macro-sim-cash-bar span:first-child {
    color: #6b7e99;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
}
.macro-sim-cash-value {
    color: #00bfff;
    font-size: 1.3rem;
    font-weight: 700;
}
.macro-sim-btn-row {
    display: flex;
    gap: 12px;
    align-items: center;
}
.macro-sim-submit-btn {
    background: linear-gradient(135deg, #0077b6, #00bfff);
    border: none;
    color: #fff;
    font-family: 'Courier New', monospace;
    font-size: 0.85rem;
    font-weight: 700;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    padding: 12px 32px;
    border-radius: 6px;
    cursor: pointer;
    transition: opacity 0.2s ease, transform 0.1s ease;
}
.macro-sim-submit-btn:hover {
    opacity: 0.9;
    transform: translateY(-1px);
}
.macro-sim-undo-btn {
    background: transparent;
    border: 1px solid #2a4060;
    color: #6b7e99;
    font-family: 'Courier New', monospace;
    font-size: 0.72rem;
    letter-spacing: 0.06em;
    padding: 8px 18px;
    border-radius: 6px;
    cursor: pointer;
    transition: border-color 0.2s ease;
}
.macro-sim-undo-btn:hover {
    border-color: #00bfff;
    color: #00bfff;
}
.macro-sim-history {
    margin-bottom: 28px;
}
.macro-sim-container table.table {
    background: #111827;
    color: #c0c8d8;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    overflow: hidden;
    font-size: 0.78rem;
}
.macro-sim-container .table thead th {
    background: #0d1220;
    color: #6b7e99;
    border-color: #1f2d3d;
    font-size: 0.65rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
}
.macro-sim-container .table tbody td {
    border-color: rgba(31,45,61,0.5);
}
.macro-sim-container .table-striped tbody tr:nth-of-type(odd) {
    background-color: rgba(17,24,39,0.6);
}
.macro-sim-chart-section {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    margin-bottom: 28px;
}
.macro-sim-chart-box {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 20px;
    min-height: 280px;
    position: relative;
}
@media (max-width: 768px) {
    .macro-sim-container {
        padding: 16px;
    }
    .macro-sim-kpi-grid {
        grid-template-columns: 1fr 1fr;
    }
    .macro-sim-input-grid {
        grid-template-columns: 1fr;
    }
    .macro-sim-chart-section {
        grid-template-columns: 1fr;
    }
    .macro-sim-header h1 {
        font-size: 1.1rem;
    }
    .macro-sim-kpi-value {
        font-size: 1.2rem;
    }
    .macro-sim-kpi-primary .macro-sim-kpi-value {
        font-size: 1.4rem;
    }
}

/* --- v1.2.0: round result panel, debrief, focus, contrast (appended) --- */
.macro-sim-round-result {
    background: #0f1a2e;
    border: 1px solid #1f2d3d;
    border-left: 3px solid #00bfff;
    border-radius: 0 8px 8px 0;
    padding: 16px 24px;
    margin-bottom: 24px;
}
.macro-sim-round-result p {
    margin: 0;
    color: #e0e6f0;
    font-size: 0.9rem;
    line-height: 1.6;
}
.macro-sim-container .macro-sim-input-hint {
    color: #8a9bb5;
}
.macro-sim-container input:focus-visible,
.macro-sim-container button:focus-visible {
    outline: 3px solid #ffd166;
    outline-offset: 2px;
}
.macro-sim-cm {
    background: #ffffff;
    padding: 16px;
    border-radius: 8px;
    text-align: left;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    color: #1a2433;
    line-height: 1.5;
}
.macro-sim-cm-head {
    display: flex;
    align-items: baseline;
    gap: 16px;
    flex-wrap: wrap;
    margin-bottom: 8px;
}
.macro-sim-cm-score-num {
    background-color: #ffffff;
    font-size: 2.4rem;
    font-weight: 700;
    color: #0b3d91;
}
.macro-sim-cm-score-of {
    background-color: #ffffff;
    font-size: 1rem;
    color: #4a5568;
}
.macro-sim-cm-tier {
    background-color: #ffffff;
    font-size: 1.1rem;
    font-weight: 700;
    color: #1a2433;
}
.macro-sim-cm-sub {
    background-color: #ffffff;
    display: flex;
    gap: 24px;
    flex-wrap: wrap;
    font-size: 0.9rem;
    color: #2d3748;
    margin-bottom: 16px;
}
.macro-sim-cm-kpis {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
    gap: 8px;
    margin-bottom: 16px;
}
.macro-sim-cm-kpi {
    background: #f1f5f9;
    border: 1px solid #cbd5e1;
    border-radius: 8px;
    padding: 8px 12px;
}
.macro-sim-cm-kpi-label {
    background-color: #f1f5f9;
    font-size: 0.75rem;
    color: #2d3748;
}
.macro-sim-cm-kpi-value {
    background-color: #f1f5f9;
    font-size: 1rem;
    font-weight: 700;
    color: #1a2433;
    font-variant-numeric: tabular-nums;
}
.macro-sim-cm-h {
    background-color: #ffffff;
    font-size: 0.95rem;
    font-weight: 700;
    color: #0b3d91;
    margin: 16px 0 8px;
}
.macro-sim-cm-tp,
.macro-sim-cm-list {
    background-color: #ffffff;
    font-size: 0.9rem;
    color: #1a2433;
}
.macro-sim-cm-list {
    padding-left: 20px;
    margin: 0;
}
.macro-sim-cm-list li {
    margin-bottom: 8px;
}
@media (prefers-reduced-motion: reduce) {
    .macro-sim-container *,
    .macro-sim-cm * {
        transition: none !important;
        animation: none !important;
    }
}

