                    brazilReturn: -0.08,
                    mexicoReturn: -0.03,
                    andeanReturn: -0.02,
                    hedgeBenefit: 0.05
                },
                {
                    scenarioKey: 'round3',
                    brazilReturn: -0.18,
                    mexicoReturn: 0.02,
                    andeanReturn: 0.01,
                    hedgeBenefit: 0.06
                },
                {
                    scenarioKey: 'round4',
                    brazilReturn: 0.04,
                    mexicoReturn: 0.05,
                    andeanReturn: 0.08,
                    hedgeBenefit: -0.03
                },
                {
                    scenarioKey: 'round5',
                    brazilReturn: -0.10,
                    mexicoReturn: -0.04,
                    andeanReturn: -0.07,
                    hedgeBenefit: 0.10
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    portfolio: 100000000,
                    initialPortfolio: 100000000,
                    cumulativeReturn: 0,
                    portfolioHistory: [],
                    returnHistory: [],
                    riskHistory: [],
                    brazilAllocHistory: [],
                    mexicoAllocHistory: [],
                    andeanAllocHistory: [],
                    cashAllocHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    brazilAlloc: 15,
                    mexicoAlloc: 10,
                    andeanAlloc: 15,
                    hedgeRatio: 20
                };
            }
            this._updateBriefing(state);
            this._setupCashCalculator();
            this._bindRepaint();
        }

        validateDecisions(decisions) {
            var brazilEl = document.getElementById('brazilInput');
            var mexicoEl = document.getElementById('mexicoInput');
            var andeanEl = document.getElementById('andeanInput');
            var hedgeEl = document.getElementById('hedgeInput');

            if (brazilEl) decisions.brazilAlloc = parseFloat(brazilEl.value);
            if (mexicoEl) decisions.mexicoAlloc = parseFloat(mexicoEl.value);
            if (andeanEl) decisions.andeanAlloc = parseFloat(andeanEl.value);
            if (hedgeEl) decisions.hedgeRatio = parseFloat(hedgeEl.value);

            if (isNaN(decisions.brazilAlloc) || decisions.brazilAlloc < 0 || decisions.brazilAlloc > 40) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('brazil_warning'), 'warning'
                );
                return false;
            }
            if (isNaN(decisions.mexicoAlloc) || decisions.mexicoAlloc < 0 || decisions.mexicoAlloc > 30) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('mexico_warning'), 'warning'
                );
                return false;
            }
            if (isNaN(decisions.andeanAlloc) || decisions.andeanAlloc < 0 || decisions.andeanAlloc > 30) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('andean_warning'), 'warning'
                );
                return false;
            }
            if (isNaN(decisions.hedgeRatio) || decisions.hedgeRatio < 0 || decisions.hedgeRatio > 100) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('hedge_warning'), 'warning'
                );
                return false;
            }

            var totalEM = decisions.brazilAlloc + decisions.mexicoAlloc + decisions.andeanAlloc;
            if (totalEM > 100) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('overalloc_warning'), 'warning'
                );
                return false;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var brazilW = d.brazilAlloc / 100;
            var mexicoW = d.mexicoAlloc / 100;
            var andeanW = d.andeanAlloc / 100;
            var emTotal = brazilW + mexicoW + andeanW;
            var cashW = 1 - emTotal;
            var hedgeW = d.hedgeRatio / 100;

            var brazilPnL = brazilW * round.brazilReturn;
            var mexicoPnL = mexicoW * round.mexicoReturn;
            var andeanPnL = andeanW * round.andeanReturn;
            var hedgePnL = hedgeW * emTotal * round.hedgeBenefit;
            var hedgeCost = hedgeW * emTotal * 0.005;
            var cashReturn = cashW * 0.01;

            var periodReturn = brazilPnL + mexicoPnL + andeanPnL + hedgePnL - hedgeCost + cashReturn;
            var periodReturnPct = periodReturn * 100;

            var pnlUSD = ds.portfolio * periodReturn;
            ds.portfolio = ds.portfolio + pnlUSD;

            var cumReturn = ((ds.portfolio / ds.initialPortfolio) - 1) * 100;
            ds.cumulativeReturn = cumReturn;

            var brazilRisk = Math.max(0, d.brazilAlloc - 20) * 2.5;
            var emRisk = Math.max(0, emTotal * 100 - 60) * 1.2;
            var hedgeDeficit = Math.max(0, (emTotal * 100) - d.hedgeRatio) * 0.4;
            var riskScore = Math.min(100, Math.round(brazilRisk + emRisk + hedgeDeficit));

            ds.portfolioHistory.push(ds.portfolio);
            ds.returnHistory.push(periodReturnPct);
            ds.riskHistory.push(riskScore);
            ds.brazilAllocHistory.push(d.brazilAlloc);
            ds.mexicoAllocHistory.push(d.mexicoAlloc);
            ds.andeanAllocHistory.push(d.andeanAlloc);
            ds.cashAllocHistory.push(Math.round(cashW * 100));

            // Score, tier and sub-scores come from one helper (_scoreParts), also used by the summary.
            var _avgRisk = ds.riskHistory.reduce(function(s, r) { return s + r; }, 0) / ds.riskHistory.length;
            var _parts = this._scoreParts(ds.cumulativeReturn, _avgRisk, ds.riskHistory.length);
            var overallScore = _parts.score;
            ds.score = overallScore;
            ds.performanceTier = _parts.tier;
            ds.performance = { overallScore: overallScore, grade: this._gradeName(_parts.tier), growthPoints: _parts.growth, riskPoints: _parts.risk };

            var self = this;
            setTimeout(((__eqilNext) => function() {
                self._updateBriefing({ currentPeriod: __eqilNext });
                self._renderRoundResult();
            })(state.currentPeriod + 1), 500);

            return {
                period: state.currentPeriod,
                overallScore: overallScore,
                score: overallScore,
                brazilAlloc: d.brazilAlloc,
                mexicoAlloc: d.mexicoAlloc,
                andeanAlloc: d.andeanAlloc,
                cashAlloc: Math.round(cashW * 100),
                hedgeRatio: d.hedgeRatio,
                periodReturn: periodReturnPct,
                pnlUSD: pnlUSD,
                portfolio: ds.portfolio,
                riskScore: riskScore,
                scenario: round.scenarioKey,
                growthPoints: _parts.growth,
                riskPoints: _parts.risk,
                excessOverCash: _parts.excess
            };
        }

        // Cumulative return in percent of a mandate left in USD cash for n rounds (cash earns 1 percent a round).
        _cashBenchmark(n) {
            return (Math.pow(1.01, n) - 1) * 100;
        }

        // One scoring function for every round and for the summary.
        // Growth (0-70) is measured against the idle-dollar benchmark: 0 points when the mandate ends
        // 8 points behind cash (the inherited portfolio left untouched), 70 points when it ends 9.5 points
        // ahead (the best zero-risk path of the teaching note). Anchors scale with the rounds played.
        // Risk (0-30): average risk index 0 gives 30 points, 60 or more gives 0.
        _scoreParts(cumReturn, avgRisk, n) {
            var rounds = Math.max(1, n || 1);
            var k = Math.min(1, rounds / 5);
            var low = 8 * k;
            var high = 9.5 * k;
            var excess = cumReturn - this._cashBenchmark(rounds);
            var growth = Math.max(0, Math.min(70, ((excess + low) / (low + high)) * 70));
            var risk = Math.max(0, Math.min(30, ((60 - avgRisk) / 60) * 30));
            var score = Math.round(Math.max(0, Math.min(100, growth + risk)));
            var tier = 'beginner';
            if (score >= 90) tier = 'excellent';
            else if (score >= 65) tier = 'very_good';
            else if (score >= 50) tier = 'good';
            return { score: score, tier: tier, growth: Math.round(growth * 10) / 10, risk: Math.round(risk * 10) / 10, excess: excess };
        }

        _gradeName(tier) {
            return { excellent: 'Excellent', very_good: 'Very Good', good: 'Good', beginner: 'Beginner' }[tier] || 'Beginner';
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('portfolioDisplay', 'domainState.portfolio',
                (v) => '$' + Math.round(v).toLocaleString());
            uiManager.bind('returnDisplay', 'results.periodReturn',
                (v) => {
                    if (v === undefined || v === null) return '—';
                    var sign = v >= 0 ? '+' : '';
                    return sign + v.toFixed(2) + '%';
                });
            uiManager.bind('cumReturnDisplay', 'domainState.cumulativeReturn',
                (v) => {
                    var sign = v >= 0 ? '+' : '';
                    return sign + v.toFixed(2) + '%';
                });
            uiManager.bind('riskDisplay', 'results.riskScore',
                (v) => (v === undefined || v === null) ? '—' : v + '/100');
        }

