        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var self = this;
            var rows = history.map(function(h, i) {
                var r = h.results || {};
                var c = self._contrib(r, i + 1);
                return {
                    n: i + 1,
                    brazil: Number(r.brazilAlloc) || 0,
                    mexico: Number(r.mexicoAlloc) || 0,
                    andean: Number(r.andeanAlloc) || 0,
                    hedge: Number(r.hedgeRatio) || 0,
                    cash: Number(r.cashAlloc) || 0,
                    ret: Number(r.periodReturn) || 0,
                    risk: Number(r.riskScore) || 0,
                    c: c
                };
            });
            var last = history[history.length - 1].results || {};
            var finalPortfolio = last.portfolio ? last.portfolio : 100000000;
            var totalReturn = ((finalPortfolio / 100000000) - 1) * 100;
            var avgRisk = rows.reduce(function(s, r) { return s + r.risk; }, 0) / rows.length;
            var parts = this._scoreParts(totalReturn, avgRisk, rows.length);
            var bench = this._cashBenchmark(rows.length);
            var benchValue = 100000000 * (1 + bench / 100);

            var insights = [];
            var gap = totalReturn - bench;
            insights.push(this._tf(gap >= 0 ? 'ins_growth_ahead' : 'ins_growth_behind', {
                v: this._money(finalPortfolio), b: this._money(benchValue), d: this._num(Math.abs(gap), 2)
            }));

            // What the run shows, read from its own history. A line appears only for a play that was made.
            var specific = [];
            var stress = rows.slice(0, 3);
            var heavy = stress.filter(function(r) { return r.brazil > 20; });
            if (heavy.length) {
                var maxB = Math.max.apply(null, heavy.map(function(r) { return r.brazil; }));
                var lost = heavy.reduce(function(s, r) { return s + r.c.brazil; }, 0);
                specific.push(this._tf('ins_brazil_heavy', { n: heavy.length, m: this._num(maxB, 0), p: this._signed(lost, 2) }));
            }
            var r2 = rows[1], r3 = rows[2], r4 = rows[3];
            if (r2 && r3 && (r2.mexico + r2.andean) - (r3.mexico + r3.andean) >= 10) {
                specific.push(this._tf('ins_r3_cut', { a: this._num(r2.mexico + r2.andean, 0), b: this._num(r3.mexico + r3.andean, 0) }));
            }
            if (r4 && r4.hedge >= 80 && (r4.brazil + r4.mexico + r4.andean) > 0) {
                specific.push(this._tf('ins_hedge_kept', { h: this._num(r4.hedge, 0), p: this._signed(r4.c.hedge, 2) }));
            }
            var avgCash = rows.reduce(function(s, r) { return s + r.cash; }, 0) / rows.length;
            if (avgCash >= 80) {
                specific.push(this._tf('ins_cash', { c: this._num(avgCash, 0) }));
            }
            var untouched = rows.length >= 5 && rows.every(function(r) {
                return r.brazil === 15 && r.mexico === 10 && r.andean === 15 && r.hedge === 20;
            });
            if (untouched) {
                specific.push(this._tf('ins_untouched', {}));
            }
            if (stress.length === 3 && !heavy.length && !untouched && avgCash < 80) {
                specific.push(this._tf('ins_brazil_low', {}));
            }
            if (r3 && r4 && r4.hedge < 80 && r3.hedge > r4.hedge && (r4.brazil + r4.mexico + r4.andean) > 0) {
                specific.push(this._tf('ins_hedge_cut', { a: this._num(r3.hedge, 0), b: this._num(r4.hedge, 0) }));
            }
            if (r2 && r3 && (r3.mexico + r3.andean) >= 30 && (r2.mexico + r2.andean) - (r3.mexico + r3.andean) < 10) {
                specific.push(this._tf('ins_r3_held', { x: this._num(r3.mexico + r3.andean, 0) }));
            }
            specific.slice(0, 3).forEach(function(x) { insights.push(x); });
            insights.push(this._tf(avgRisk > 0 ? 'ins_risk' : 'ins_risk_zero', { r: this._num(avgRisk, 0) }));

            // Turning point: the round furthest behind cash; when no round fell behind, the round furthest ahead.
            var worst = rows.reduce(function(m, r) { return r.ret < m.ret ? r : m; }, rows[0]);
            var best = rows.reduce(function(m, r) { return r.ret > m.ret ? r : m; }, rows[0]);
            var tp = worst.ret < 1 ? worst : best;
            var turningPoint = this._tf(worst.ret < 1 ? 'tp_behind' : 'tp_ahead', {
                t: this._t('round' + tp.n + '_title'),
                r: this._signed(tp.ret, 2),
                l: this._breakdown(tp.c)
            });

            return {
                overallScore: parts.score,
                score: parts.score,
                totalScore: parts.score,
                composite: parts.score,
                performance: parts.tier,
                performanceKey: 'tier_' + parts.tier,
                performanceLabel: this._t('tier_' + parts.tier),
                growthPoints: parts.growth,
                riskPoints: parts.risk,
                finalPortfolio: this._money(finalPortfolio),
                totalReturn: this._signed(totalReturn, 2) + '%',
                cashBenchmark: this._signed(bench, 2) + '%',
                avgRisk: Math.round(avgRisk) + '/100',
                turningPoint: turningPoint,
                insights: insights,
                questions: [this._t('dq_1'), this._t('dq_2'), this._t('dq_3')]
            };
        }

        formatCompletionMessage(summary) {
            summary = summary || {};
            if (summary.overallScore === undefined || summary.overallScore === null) {
                return '<div class="macro-sim-cm"><p>' + this._t('cm_no_data') + '</p></div>';
            }
            var self = this;
            var li = function(arr) { return (arr || []).map(function(x) { return '<li>' + x + '</li>'; }).join(''); };
            var kpi = function(labelKey, value) {
                return '<div class="macro-sim-cm-kpi"><div class="macro-sim-cm-kpi-label">' + self._t(labelKey) +
                    '</div><div class="macro-sim-cm-kpi-value">' + value + '</div></div>';
            };
            return '<div class="macro-sim-cm">' +
                '<div class="macro-sim-cm-head">' +
                    '<div class="macro-sim-cm-score"><span class="macro-sim-cm-score-num">' + summary.overallScore + '</span><span class="macro-sim-cm-score-of">/100</span></div>' +
                    '<div class="macro-sim-cm-tier">' + (summary.performanceLabel || '') + '</div>' +
                '</div>' +
                '<div class="macro-sim-cm-sub">' +
                    '<span>' + this._t('cm_growth') + ': <strong>' + this._num(summary.growthPoints, 1) + '/70</strong></span>' +
                    '<span>' + this._t('cm_risk') + ': <strong>' + this._num(summary.riskPoints, 1) + '/30</strong></span>' +
                '</div>' +
                '<div class="macro-sim-cm-kpis">' +
                    kpi('cm_final', summary.finalPortfolio) +
                    kpi('cm_return', summary.totalReturn) +
                    kpi('cm_bench', summary.cashBenchmark) +
                    kpi('cm_avgrisk', summary.avgRisk) +
                '</div>' +
                '<h4 class="macro-sim-cm-h">' + this._t('cm_tp_heading') + '</h4>' +
                '<p class="macro-sim-cm-tp">' + (summary.turningPoint || '') + '</p>' +
                '<h4 class="macro-sim-cm-h">' + this._t('cm_ins_heading') + '</h4>' +
                '<ul class="macro-sim-cm-list">' + li(summary.insights) + '</ul>' +
                '<h4 class="macro-sim-cm-h">' + this._t('cm_dq_heading') + '</h4>' +
                '<ol class="macro-sim-cm-list">' + li(summary.questions) + '</ol>' +
            '</div>';
        }

        // ---- text helpers ----
        _lang() {
            var l = (window.vcI18n && window.vcI18n._lang) || (document.documentElement && document.documentElement.lang) || 'en';
            return String(l).toLowerCase().slice(0, 2);
        }

        _t(key) {
            try { return window.mySimulation.t(key); } catch (e) { return key; }
        }

        _tf(key, vars) {
            var out = this._t(key);
            Object.keys(vars || {}).forEach(function(k) { out = out.split('{' + k + '}').join(vars[k]); });
            return out;
        }

        _num(v, d) {
            var txt = (Number(v) || 0).toFixed(d);
            return this._lang() === 'es' ? txt.replace('.', ',') : txt;
        }

        _signed(v, d) {
            return ((Number(v) || 0) >= 0 ? '+' : '−') + this._num(Math.abs(Number(v) || 0), d);
        }

        _money(v) {
            return 'USD ' + this._num(v / 1000000, 2) + ' M';
        }

        // Points of return each position added in a round, from the stored results of that round.
        _contrib(res, period) {
            var idx = Math.min(Math.max(1, period || res.period || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var b = (Number(res.brazilAlloc) || 0) / 100;
            var m = (Number(res.mexicoAlloc) || 0) / 100;
            var a = (Number(res.andeanAlloc) || 0) / 100;
            var h = (Number(res.hedgeRatio) || 0) / 100;
            var em = b + m + a;
            return {
                brazil: b * round.brazilReturn * 100,
                mexico: m * round.mexicoReturn * 100,
                andean: a * round.andeanReturn * 100,
                hedge: h * em * (round.hedgeBenefit - 0.005) * 100,
                cash: (1 - em) * 1
            };
        }

        _breakdown(c) {
            return this._tf('breakdown', {
                b: this._signed(c.brazil, 2), m: this._signed(c.mexico, 2), a: this._signed(c.andean, 2),
                h: this._signed(c.hedge, 2), c: this._signed(c.cash, 2)
            });
        }

        // The result of the last scored round stays on screen until the next one.
        _renderRoundResult() {
            var panel = document.getElementById('roundResultPanel');
            var text = document.getElementById('roundResultText');
            if (!panel || !text) return;
            var st = window.mySimulation && window.mySimulation.state;
            var hist = (st && st.history) || [];
            if (!hist.length || !hist[hist.length - 1].results) {
                panel.style.display = 'none';
                text.textContent = '';
                return;
            }
            var res = hist[hist.length - 1].results;
            var n = hist.length;
            text.textContent = this._tf('round_result', {
                n: n, r: this._signed(res.periodReturn, 2), k: res.riskScore, l: this._breakdown(this._contrib(res, n))
            });
            panel.style.display = '';
        }

        _applyAria() {
            var p = document.getElementById('portfolioChart');
            if (p) p.setAttribute('aria-label', this._t('chart_portfolio_aria'));
            var a = document.getElementById('allocationChart');
            if (a) a.setAttribute('aria-label', this._t('chart_alloc_aria'));
        }

        _bindRepaint() {
            if (this._repaintBound) return;
            this._repaintBound = true;
            var self = this;
            var repaint = function() {
                try {
                    if (window.mySimulation && window.mySimulation.state) {
                        var st = window.mySimulation.state;
                        var done = (st.history || []).length >= self.ROUNDS.length;
                        self._updateBriefing({ currentPeriod: done ? self.ROUNDS.length : st.currentPeriod });
                    }
                    self._renderRoundResult();
                    self._applyAria();
                } catch (e) { /* nothing to repaint yet */ }
            };
            document.addEventListener('express:langchanged', function() { setTimeout(repaint, 0); });
            setTimeout(function() {
                var bus = window.mySimulation && window.mySimulation.eventBus;
                if (bus && typeof bus.on === 'function') {
                    bus.on('language:changed', function() { setTimeout(repaint, 0); });
                    bus.on('period:undone', function() { setTimeout(repaint, 0); });
                }
                repaint();
            }, 0);
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.periodReturn < -5) return window.mySimulation.t('hint_heavy_loss');
            if (results.riskScore > 60) return window.mySimulation.t('hint_high_risk');
            if (results.periodReturn > 0 && results.riskScore < 30) return window.mySimulation.t('hint_good_balance');
            if (results.hedgeRatio < 10 && results.periodReturn < 0) return window.mySimulation.t('hint_low_hedge');
            return null;
        }

